1	// --- Price list: insurance values and base premiums ---
2	
3	/** The price list states one insurance value and one base premium per item kind. */
4	interface ListedPrice {
5	  insuranceValue: number;
6	  basePremium: number;
7	}
8	
9	const MAIN_ITEM_PRICE_LIST: Record<string, ListedPrice> = {
10	  sword: { insuranceValue: 1000, basePremium: 100 },
11	  amulet: { insuranceValue: 600, basePremium: 60 },
12	  staff: { insuranceValue: 800, basePremium: 80 },
13	  potion: { insuranceValue: 400, basePremium: 40 },
14	};
15	
16	const COMPONENT_PRICE: ListedPrice = { insuranceValue: 250, basePremium: 25 };
17	const COMPONENT_BLOCK_SIZE = 3;
18	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
19	
20	// --- Premium modifiers ---
21	const CURSE_SURCHARGE = 0.5;
22	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
23	const SURCHARGED_ENCHANTMENT_LEVEL = 5;
24	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
25	const LOYALTY_DISCOUNT = 0.2;
26	const LOYALTY_YEARS = 2;
27	const FIRST_INSURANCE_SURCHARGE = 0.1;
28	const PROCESSING_FEE = 5;
29	
30	// --- Claim processing ---
31	const DEDUCTIBLE_PER_DAMAGE = 100;
32	const PAYOUT_CAP_MULTIPLE = 2;
33	const HALF_REIMBURSED_ENCHANTMENT_LEVEL = 8;
34	const HALF_REIMBURSEMENT = 0.5;
35	const FULLY_REIMBURSED_MATERIAL = "dragon";
36	const FULL_REIMBURSEMENT = 1;
37	/** What a damage is reimbursed at when no special clause applies. */
38	const STANDARD_REIMBURSEMENT = 1;
39	
40	export interface Customer {
41	  yearsWithMHPCO: number;
42	}
43	
44	export interface Item {
45	  type: string;
46	  material?: string;
47	  enchantment?: number;
48	  cursed?: boolean;
49	}
50	
51	export interface QuoteStep {
52	  op: "quote";
53	  items: Item[];
54	}
55	
56	export interface Damage {
57	  itemType: string;
58	  amount: number;
59	}
60	
61	export interface Incident {
62	  cause: string;
63	  damages: Damage[];
64	}
65	
66	export interface ClaimStep {
67	  op: "claim";
68	  policy: number;
69	  incident: Incident;
70	}
71	
72	export type Step = QuoteStep | ClaimStep;
73	
74	export interface Scenario {
75	  customer: Customer;
76	  steps: Step[];
77	}
78	
79	export interface ScenarioResults {
80	  results: unknown[];
81	}
82	
83	const COMPONENT_TYPES = ["rune", "moonstone"];
84	
85	/**
86	 * An item that names no enchantment carries none: a rune has no enchantment
87	 * level at all, and the MHPCO reads that as level 0 wherever a clause draws an
88	 * enchantment line.
89	 */
90	function enchantmentLevelOf(item: Item): number {
91	  return item.enchantment ?? 0;
92	}
93	
94	function isComponent(item: Item): boolean {
95	  return COMPONENT_TYPES.includes(item.type);
96	}
97	
98	/** Everything the price list prices individually, as opposed to by alike group. */
99	function isMainItem(item: Item): boolean {
100	  return item.type in MAIN_ITEM_PRICE_LIST;
101	}
102	
103	/** The MHPCO insures an item only if its type is named in the price list. */
104	function isInsurable(item: Item): boolean {
105	  return isMainItem(item) || isComponent(item);
106	}
107	
108	/**
109	 * Admission is the MHPCO's decision about what it is willing to cover at all,
110	 * taken before the contract is opened or priced: an item the price list does
111	 * not name cannot be covered, so the whole policy is refused.
112	 */
113	function admitToPolicy(items: Item[]): void {
114	  for (const item of items) {
115	    if (!isInsurable(item)) {
116	      throw new Error(`The MHPCO price list covers no item of type "${item.type}".`);
117	    }
118	  }
119	}
120	
121	/** Components are "alike" when they share a component type. */
122	function groupAlikeComponents(components: Item[]): Map<string, number> {
123	  const groupSizes = new Map<string, number>();
124	  for (const component of components) {
125	    const alikeness = component.type;
126	    groupSizes.set(alikeness, (groupSizes.get(alikeness) ?? 0) + 1);
127	  }
128	  return groupSizes;
129	}
130	
131	/** A building block of 3 alike components is offered at a special base premium. */
132	function alikeComponentGroupBasePremium(groupSize: number): number {
133	  return groupSize === COMPONENT_BLOCK_SIZE
134	    ? COMPONENT_BLOCK_BASE_PREMIUM
135	    : groupSize * COMPONENT_PRICE.basePremium;
136	}
137	
138	function mainItemsBasePremium(mainItems: Item[]): number {
139	  return mainItems.reduce((sum, item) => sum + MAIN_ITEM_PRICE_LIST[item.type].basePremium, 0);
140	}
141	
142	function componentsBasePremium(components: Item[]): number {
143	  let premium = 0;
144	  for (const groupSize of groupAlikeComponents(components).values()) {
145	    premium += alikeComponentGroupBasePremium(groupSize);
146	  }
147	  return premium;
148	}
149	
150	function policyBasePremium(items: Item[]): number {
151	  return (
152	    mainItemsBasePremium(items.filter(isMainItem)) +
153	    componentsBasePremium(items.filter(isComponent))
154	  );
155	}
156	
157	/**
158	 * An item-specific surcharge is a rate on the affected item's own base premium,
159	 * not on the policy's. Only main items carry a per-item base premium; a
160	 * component's belongs to its alike group, so the specification fixes no
161	 * surcharge for a cursed or highly enchanted component.
162	 *
163	 * Open question -- no example in the specification covers one, and no test
164	 * pins the outcome, so the behaviour here is undefined rather than decided:
165	 * the lookup misses and the premium becomes NaN. Settle it with a test before
166	 * relying on it; a quote is never reached with such an item today only because
167	 * no example produces one.
168	 */
169	function surchargeOnOwnBasePremium(item: Item, rate: number): number {
170	  return MAIN_ITEM_PRICE_LIST[item.type].basePremium * rate;
171	}
172	
173	function curseSurcharge(item: Item): number {
174	  return item.cursed === true ? surchargeOnOwnBasePremium(item, CURSE_SURCHARGE) : 0;
175	}
176	
177	/**
178	 * The premium surcharge for a highly enchanted item, from enchantment level 5
179	 * upwards. The claim side draws its own, higher enchantment line at level 8 for
180	 * half reimbursement -- two separate clauses, not one threshold used twice.
181	 */
182	function highEnchantmentSurcharge(item: Item): number {
183	  return enchantmentLevelOf(item) >= SURCHARGED_ENCHANTMENT_LEVEL
184	    ? surchargeOnOwnBasePremium(item, HIGH_ENCHANTMENT_SURCHARGE)
185	    : 0;
186	}
187	
188	/** Item-specific surcharges apply to the base premium of the affected item. */
189	function itemSurcharges(items: Item[]): number {
190	  return items.reduce(
191	    (sum, item) => sum + curseSurcharge(item) + highEnchantmentSurcharge(item),
192	    0,
193	  );
194	}
195	
196	/** A customer is long-standing from 2 years of business with MHPCO onwards. */
197	function loyaltyDiscount(basePremium: number, customer: Customer): number {
198	  return customer.yearsWithMHPCO >= LOYALTY_YEARS ? basePremium * LOYALTY_DISCOUNT : 0;
199	}
200	
201	/**
202	 * Every item in a quote is treated as a first insurance, regardless of customer
203	 * history, so the initial assessment surcharge carries no condition.
204	 */
205	function firstInsuranceSurcharge(basePremium: number): number {
206	  return basePremium * FIRST_INSURANCE_SURCHARGE;
207	}
208	
209	/** Customers receive a discount on each contract after their first. */
210	function followUpContractDiscount(basePremium: number, contractOrdinal: number): number {
211	  return contractOrdinal > 1 ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT : 0;
212	}
213	
214	/** Policy-wide modifiers apply to the policy base premium (the sum of all item base premiums). */
215	function policyWideModifiers(
216	  basePremium: number,
217	  customer: Customer,
218	  contractOrdinal: number,
219	): number {
220	  return (
221	    firstInsuranceSurcharge(basePremium) -
222	    loyaltyDiscount(basePremium, customer) -
223	    followUpContractDiscount(basePremium, contractOrdinal)
224	  );
225	}
226	
227	/**
228	 * Which side of the MHPCO's ledger an amount sits on. The office is owed a
229	 * premium and owes a payout, and that is the only thing that distinguishes how
230	 * the two are rounded.
231	 */
232	type LedgerSide = "owedToMHPCO" | "owedByMHPCO";
233	
234	/**
235	 * All amounts are rounded to whole G in the MHPCO's favour. One rule, one home:
236	 * the direction is not a second decision but a consequence of which side of the
237	 * ledger the amount is on -- the office keeps the fraction either way, rounding
238	 * up what it is owed and down what it owes. Change the office's idea of its own
239	 * favour here and both the premium and the payout follow.
240	 */
241	function roundedInMHPCOsFavour(amount: number, side: LedgerSide): number {
242	  return side === "owedToMHPCO" ? Math.ceil(amount) : Math.floor(amount);
243	}
244	
245	/**
246	 * The MHPCO prices a policy in one order: the policy base premium, then the
247	 * modifiers at their own scopes, then the processing fee at the very end.
248	 * Item-specific modifiers are charged against the base premium of the affected
249	 * item; policy-wide modifiers against the policy base premium. Only this final
250	 * amount is rounded -- intermediate amounts stay fractional.
251	 *
252	 * Pricing assumes an admitted policy: every item is named in the price list,
253	 * because admission is decided before a contract is opened or priced at all.
254	 */
255	function quotePremium(items: Item[], customer: Customer, contractOrdinal: number): number {
256	  const basePremium = policyBasePremium(items);
257	  return roundedInMHPCOsFavour(
258	    basePremium +
259	      itemSurcharges(items) +
260	      policyWideModifiers(basePremium, customer, contractOrdinal) +
261	      PROCESSING_FEE,
262	    "owedToMHPCO",
263	  );
264	}
265	
266	/**
267	 * How many contracts the customer has taken out with MHPCO up to and including
268	 * the quote at this step. Every step is a quote today, so a step's position in
269	 * the scenario is its contract ordinal.
270	 */
271	function contractOrdinalOfStep(stepIndex: number): number {
272	  return stepIndex + 1;
273	}
274	
275	/**
276	 * What the price list says one insured item is worth. This is the item's
277	 * unmodified value: premium modifiers price the risk of covering the item and
278	 * never change what it is worth, and the block offered on 3 alike components
279	 * is a premium offer, so each component is still insured at its own value.
280	 */
281	function insuranceValueOf(item: Item): number {
282	  return isComponent(item)
283	    ? COMPONENT_PRICE.insuranceValue
284	    : MAIN_ITEM_PRICE_LIST[item.type].insuranceValue;
285	}
286	
287	/** What the MHPCO would have to pay out if every insured item were destroyed. */
288	function insuranceSum(items: Item[]): number {
289	  return items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
290	}
291	
292	
293	/**
294	 * A policy created by a quote step: the MHPCO's remaining obligation under one
295	 * contract, measured two ways. `insuredItems` is the fixed coverage the contract
296	 * was written against; `remainingCap` is the money left under it, derived from
297	 * that coverage at opening and drawn down by each claim. They belong together
298	 * because the cap is a function of the coverage, not an unrelated counter.
299	 */
300	interface Policy {
301	  insuredItems: Item[];
302	  remainingCap: number;
303	}
304	
305	function openPolicy(items: Item[]): Policy {
306	  return { insuredItems: items, remainingCap: insuranceSum(items) * PAYOUT_CAP_MULTIPLE };
307	}
308	
309	/**
310	 * Damage to an item of enchantment level 8 or more is reimbursed at half the
311	 * damage amount. This is the claim side's own enchantment line, above the
312	 * level 5 that earns a premium surcharge.
313	 */
314	function isHalfReimbursed(item: Item): boolean {
315	  return enchantmentLevelOf(item) >= HALF_REIMBURSED_ENCHANTMENT_LEVEL;
316	}
317	
318	/** Damage to an item made of dragon material is fully reimbursed. */
319	function isFullyReimbursed(item: Item): boolean {
320	  return item.material === FULLY_REIMBURSED_MATERIAL;
321	}
322	
323	/**
324	 * The fraction of a damage amount the reimbursement clauses allow for this
325	 * item, before the deductible is taken. This is the one place a clause is
326	 * chosen, and the order is the specification's precedence rule rather than an
327	 * accident of writing: where both special clauses cover an item, "the 50 %
328	 * rule wins", so half reimbursement is tested first. Failing both, the damage
329	 * is reimbursed at the standard rate.
330	 *
331	 * The two clauses draw on separate knowledge and can change apart -- one reads
332	 * an enchantment level, the other a material -- so that full reimbursement
333	 * currently equals the standard rate is a coincidence of the present price
334	 * book, not one fact written twice. The clause says "full reimbursement is
335	 * owed here"; the standard rate says "no clause applies". No example can tell
336	 * them apart today, which is why the dragon clause is stated and not inferred.
337	 */
338	function reimbursementRateFor(damagedItem: Item): number {
339	  if (isHalfReimbursed(damagedItem)) return HALF_REIMBURSEMENT;
340	  if (isFullyReimbursed(damagedItem)) return FULL_REIMBURSEMENT;
341	  return STANDARD_REIMBURSEMENT;
342	}
343	
344	/** The share of a damage the MHPCO reimburses before the deductible is taken. */
345	function reimbursableDamage(damage: Damage, damagedItem: Item): number {
346	  return damage.amount * reimbursementRateFor(damagedItem);
347	}
348	
349	/**
350	 * The deductible is the claimant's own share of each damage event: the MHPCO
351	 * reimburses what the damage exceeds it by.
352	 *
353	 * Adopted reading -- the specification says only that "a deductible of 100 G
354	 * applies per damage event", and fixes no outcome for a damage smaller than
355	 * the deductible. A deductible reduces a reimbursement; it does not bill the
356	 * claimant, so a damage at or below it is reimbursed at nothing rather than
357	 * at a negative amount. Settle it against the MHPCO before relying on it.
358	 */
359	function reimbursementAfterDeductible(damage: Damage, damagedItem: Item): number {
360	  const excessOverDeductible = reimbursableDamage(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;
361	  return Math.max(excessOverDeductible, 0);
362	}
363	
364	interface ClaimResult {
365	  payout: number;
366	  remainingCap: number;
367	}
368	
369	/**
370	 * The insured item a damage entry refers to.
371	 *
372	 * The specification does reject a claim that names an item the policy does not
373	 * cover, so this throw is the start of a real MHPCO decision rather than a
374	 * type-system formality -- but no active test pins it yet, and the rejection it
375	 * will eventually serve is broader than what happens here (it also covers more
376	 * damage entries of a type than the policy insures). Treat the current throw as
377	 * unpinned: the behaviour stands, the clause is not yet designed.
378	 */
379	function damagedItemIn(policy: Policy, damage: Damage): Item {
380	  const item = policy.insuredItems.find((insured) => insured.type === damage.itemType);
381	  if (item === undefined) {
382	    throw new Error(`The policy covers no item of type "${damage.itemType}".`);
383	  }
384	  return item;
385	}
386	
387	/** What the policy's clauses owe for an incident, before the cap is consulted. */
388	function reimbursementOwed(policy: Policy, incident: Incident): number {
389	  return incident.damages.reduce(
390	    (sum, damage) => sum + reimbursementAfterDeductible(damage, damagedItemIn(policy, damage)),
391	    0,
392	  );
393	}
394	
395	/**
396	 * What the policy is still permitted to pay. The total payout per policy is
397	 * capped, so a claim for more than the cap still carries is not refused -- the
398	 * owed amount is reduced to what remains.
399	 *
400	 * This is the cap's own decision, separate from what the clauses owe: the two
401	 * answer different questions ("what does this damage deserve?" against "how
402	 * much of the contract is left?") and change on separate occasions.
403	 */
404	function payoutPermittedByCap(owed: number, remainingCap: number): number {
405	  return Math.min(owed, remainingCap);
406	}
407	
408	/**
409	 * Settling an incident both pays the claimant and uses up part of the cap the
410	 * policy carries for the rest of its life, so the settled policy is the second
411	 * half of the outcome rather than a side effect: a claim leaves the policy in a
412	 * new state, and later claims against it see that state.
413	 */
414	function settleClaim(policy: Policy, incident: Incident): { result: ClaimResult; policy: Policy } {
415	  const payout = roundedInMHPCOsFavour(
416	    payoutPermittedByCap(reimbursementOwed(policy, incident), policy.remainingCap),
417	    "owedByMHPCO",
418	  );
419	  const remainingCap = policy.remainingCap - payout;
420	  return {
421	    result: { payout, remainingCap },
422	    policy: { ...policy, remainingCap },
423	  };
424	}
425	
426	export function runScenario(scenario: Scenario): ScenarioResults {
427	  /** Policies opened so far, addressed the way the input does: by the index of the quote step that opened each. */
428	  const policies = new Map<number, Policy>();
429	
430	  /**
431	   * A claim naming a step that opened no policy is outside the specification --
432	   * no example and no test describes it -- so this guard exists only to keep the
433	   * lookup total for the type system.
434	   */
435	  const policyOpenedBy = (quoteStepIndex: number): Policy => {
436	    const policy = policies.get(quoteStepIndex);
437	    if (policy === undefined) {
438	      throw new Error(`No policy was created by step ${String(quoteStepIndex)}.`);
439	    }
440	    return policy;
441	  };
442	
443	  const results = scenario.steps.map((step, stepIndex) => {
444	    if (step.op === "claim") {
445	      const { result, policy } = settleClaim(policyOpenedBy(step.policy), step.incident);
446	      policies.set(step.policy, policy);
447	      return result;
448	    }
449	    admitToPolicy(step.items);
450	    policies.set(stepIndex, openPolicy(step.items));
451	    return {
452	      premium: quotePremium(step.items, scenario.customer, contractOrdinalOfStep(stepIndex)),
453	    };
454	  });
455	  return { results };
456	}
