cp src/claim-office.ts /tmp/co.bak && python3 - <<'PY'
import re
p='src/claim-office.ts'
s=open(p).read()

old = '''/**
 * The insured item a damage entry refers to.
 *
 * The specification does reject a claim that names an item the policy does not
 * cover, so this throw is the start of a real MHPCO decision rather than a
 * type-system formality -- but no active test pins it yet, and the rejection it
 * will eventually serve is broader than what happens here (it also covers more
 * damage entries of a type than the policy insures). Treat the current throw as
 * unpinned: the behaviour stands, the clause is not yet designed.
 */
function damagedItemIn(policy: Policy, damage: Damage): Item {
  const item = policy.insuredItems.find((insured) => insured.type === damage.itemType);
  if (item === undefined) {
    throw new Error(`The policy covers no item of type "${damage.itemType}".`);
  }
  return item;
}
'''

new = '''/** The policy covers a damage entry only if it insures an item of that type. */
function coversItemType(policy: Policy, itemType: string): boolean {
  return policy.insuredItems.some((insured) => insured.type === itemType);
}

/**
 * Admission is the MHPCO's decision about whether it will settle an incident at
 * all, taken before any clause is applied -- the claim-side counterpart of
 * admitting items to a policy. A damage the policy does not cover cannot be
 * reimbursed, so the whole claim is refused rather than settled in part.
 */
function admitClaim(policy: Policy, incident: Incident): void {
  for (const damage of incident.damages) {
    if (!coversItemType(policy, damage.itemType)) {
      throw new Error(`The policy covers no item of type "${damage.itemType}".`);
    }
  }
}

/**
 * The insured item a damage entry refers to. Settling assumes an admitted
 * incident: every damage names a covered item, because admission is decided
 * before any clause is applied, so the miss here is unreachable and guards only
 * the type system.
 */
function damagedItemIn(policy: Policy, damage: Damage): Item {
  const item = policy.insuredItems.find((insured) => insured.type === damage.itemType);
  if (item === undefined) {
    throw new Error(`The policy covers no item of type "${damage.itemType}".`);
  }
  return item;
}
'''
assert old in s
s=s.replace(old,new)

old2='''function settleClaim(policy: Policy, incident: Incident): { result: ClaimResult; policy: Policy } {
  const payout = roundedInMHPCOsFavour('''
new2='''function settleClaim(policy: Policy, incident: Incident): { result: ClaimResult; policy: Policy } {
  admitClaim(policy, incident);
  const payout = roundedInMHPCOsFavour('''
assert old2 in s
s=s.replace(old2,new2)
open(p,'w').write(s)
